  "n_points": 10,
  "replicates": 3,
  "controls": [
    "vehicle-only (DMSO at matched final fraction) = 100% activity control",
    "no-enzyme wells = background/0% activity for ADP-Glo",
    "no-substrate wells (ATP-only) to confirm ADP-Glo depletion background",
    "reference inhibitor well (any established TAK1 inhibitor available in-lab) as positive inhibition control",
    "compound-only blank at top concentration to detect luminescence quenching/interference by CHEMBL1077979"
